<?php
declare(strict_types=1);
namespace App;
final class Identity {
    public static function routes():array{return ['/login'=>self::login(...),'/logout'=>self::logout(...),'/profile'=>self::profile(...),'/users'=>self::users(...),'/permissions'=>self::permissions(...),'/roles'=>self::roles(...),'/settings/users'=>UserController::index(...),'/settings/users/new'=>static fn()=>UserController::edit(true),'/settings/users/edit'=>static fn()=>UserController::edit(false),'/admin/roles'=>RoleController::index(...),'/settings/roles'=>RoleController::index(...),'/settings/roles/new'=>static fn()=>RoleController::edit(true),'/settings/roles/edit'=>static fn()=>RoleController::edit(false),'/settings/roles/delete'=>RoleController::delete(...)];}
    public static function login():string {
        $error='';if($_SERVER['REQUEST_METHOD']==='POST'){Http::checkCsrf();$ip=$_SERVER['REMOTE_ADDR']??'';$key='login_'.hash('sha256',$ip);$file=APP_ROOT.'/runtime/'.$key.'.json';$hits=is_file($file)?json_decode(file_get_contents($file),true):[];$hits=array_filter($hits??[],fn($t)=>$t>time()-900);if(count($hits)>=10)throw new \RuntimeException('Слишком много попыток входа. Повторите через 15 минут.',429);
            if(Auth::login(trim((string)($_POST['username']??'')),(string)($_POST['password']??''))){@unlink($file);Http::redirect(Auth::landing());}$hits[]=time();file_put_contents($file,json_encode($hits),LOCK_EX);$error='<div class="form-alert alert-error" role="alert"><span class="alert-mark" aria-hidden="true">×</span><div class="alert-body"><div class="alert-body-title">Неверный логин или пароль.</div></div></div>';
        }
        $presets=LocalTestLogin::presets();
        $serverPresets=$presets?[]:ServerLoginPresets::view();
        if ($presets || $serverPresets) header('Cache-Control: no-store, private');
        return View::login($error,$presets,$serverPresets);
    }
    public static function logout():never {Http::checkCsrf();if($_SERVER['REQUEST_METHOD']!=='POST')throw new \RuntimeException('Метод не поддерживается',405);$_SESSION=[];session_regenerate_id(true);Http::redirect('/login');}
    public static function profile():string {
        $u=Auth::user();if(!$u)Http::redirect('/login');$notice='';
        if($_SERVER['REQUEST_METHOD']==='POST'){Http::checkCsrf();$nextVersion=DB::transaction(function()use($u):int {$q=DB::pdo()->prepare('SELECT password_hash,auth_version FROM users WHERE id=? FOR UPDATE');$q->execute([$u['id']]);$current=$q->fetch();if(!$current||!password_verify((string)($_POST['current_password']??''),$current['password_hash']))throw new \RuntimeException('Текущий пароль неверен',422);$pass=(string)($_POST['password']??'');if(strlen($pass)<12)throw new \RuntimeException('Пароль должен содержать не менее 12 символов',422);Audit::record('password.change','user',$u['id']);DB::pdo()->prepare('UPDATE users SET name=?,password_hash=?,version=version+1,auth_version=auth_version+1 WHERE id=?')->execute([trim((string)($_POST['name']??$u['name'])),password_hash($pass,PASSWORD_DEFAULT),$u['id']]);return (int)$current['auth_version']+1;});$_SESSION['auth_version']=$nextVersion;session_regenerate_id(true);unset($_SESSION['csrf']);$notice='<p role="status">Профиль обновлён</p>';}
        $u=Auth::user();return View::page('Мой профиль',View::heading('Мой профиль','Ваша учётная запись и назначенная роль','user').$notice.'<section class="table-card registry-ui-card ui-detail-card demo-form-width"><section class="panel-section"><h2 class="section-title">Учётная запись</h2><div class="demo-value-pair"><span class="registry-ui-secondary">Имя</span><span class="registry-ui-primary">'.View::e($u['name']).'</span><span class="registry-ui-secondary">Логин</span><span class="registry-ui-primary">'.View::e($u['username']).'</span><span class="registry-ui-secondary">Роль</span><span class="registry-ui-primary">'.View::e($u['role_label']).'</span><span class="registry-ui-secondary">Статус</span><span><span class="badge badge-ok">Активен</span></span></div></section><section class="panel-section"><p class="registry-ui-secondary">Доступ к страницам определяется назначенной ролью.</p></section></section>');
    }
    public static function users():string {return UserController::index();}
    public static function permissions():string {Auth::requirePermission('identity.permissions');$rows='';foreach(DB::pdo()->query('SELECT r.name,rp.permission_key FROM roles r JOIN role_permissions rp ON rp.role_id=r.id ORDER BY r.id,rp.permission_key')as $r)$rows.='<tr><td>'.View::e($r['name']).'</td><td>'.View::e($r['permission_key']).'</td></tr>';return View::page('Права доступа',View::heading('Права доступа','Информационная матрица текущих прав.').'<table class="registry-ui-table"><thead><tr><th>Роль</th><th>Разрешение</th></tr></thead><tbody>'.$rows.'</tbody></table>');}
    public static function roles():string {Auth::requirePermission('identity.permissions');$rows='';foreach(DB::pdo()->query('SELECT r.id,r.name,COUNT(u.id) users FROM roles r LEFT JOIN users u ON u.role=r.id GROUP BY r.id,r.name ORDER BY r.id')as $r)$rows.='<tr><td>'.View::e($r['id']).'</td><td>'.View::e($r['name']).'</td><td>'.View::e($r['users']).'</td></tr>';return View::page('Роли',View::heading('Роли','Каждому пользователю назначается одна роль.').'<table class="registry-ui-table"><thead><tr><th>Код</th><th>Роль</th><th>Пользователей</th></tr></thead><tbody>'.$rows.'</tbody></table><a class="btn" href="/permissions">Права доступа</a>');}
}
